#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_prepend_enough_space_no_resize(void) {
    // Setup: create a buffer with enough space to prepend without resizing
    // Let's use initial content "World", buffer size 16 (enough for "HelloWorld\0")
    buffer_t *buf = helper_create_buffer_with_content("World");
    TEST_ASSERT_NOT_NULL(buf);

    // Manually ensure buffer size is large enough (simulate buffer_new_with_size if needed)
    // But helper_create_buffer_with_content should allocate enough for the string,
    // so we need to ensure buf->len > strlen("Hello") + strlen("World")
    // For this test, let's assume helper_create_buffer_with_content allocates at least strlen("World") + 1,
    // so we increase the size if needed.
    size_t required = strlen("Hello") + strlen("World");
    if (buf->len <= required) {
        // Increase buffer size to 16
        int resize_ret = buffer_resize(buf, 16);
        TEST_ASSERT_EQUAL_INT(0, resize_ret);
    }

    // Test: prepend "Hello" to the buffer
    int ret = buffer_prepend(buf, "Hello");
    TEST_ASSERT_EQUAL_INT(0, ret);

    // Assertions: buffer content should be "HelloWorld"
    helper_assert_buffer_content(buf, "HelloWorld");
    helper_assert_buffer_length(buf, strlen("HelloWorld"));
    // Buffer size should be at least required+1, but we set it to 16
    helper_assert_buffer_size(buf, 16);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_prepend_enough_space_no_resize);
    return UNITY_END();
}

